Page_CommonActTimeTokenView = class("Page_CommonActTimeTokenView",Page_CommonActViewBase)

function Page_CommonActTimeTokenView:GetPageName()
    return "Page_CommonActTimeTokenView"
end

function Page_CommonActTimeTokenView:initialize()

end

function Page_CommonActTimeTokenView:OnAwake()
    self.center = UIUtil.GetChild("Center", self.gameObject)
    self.TimeTokenView= UIUtil.GetChild("TimeTokenView", self.gameObject)
    self.BonusPreview= UIUtil.GetChild("BonusPreview", self.TimeTokenView)
    self.GetLevelView= UIUtil.GetChild("GetLevelView", self.gameObject)
    self.TaskView= UIUtil.GetChild("TaskView", self.gameObject)

    CommonHelper:HButtonSetCallback("BtnHelp", self.center, function(data)
        CommonHelper:ShowHelpView(PageDetailType.ActTimeToken)
    end)
    CommonHelper:HButtonSetCallback("BtnGetLv", self.center, function(data)
        if TimeTokenManager:Get():GetTimeTokenInfoData().lev>=TimeTokenManager:Get():GetTimeTokenInfoData().maxLev then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenLevelMax))
            return
        end
        local cfg = CommonHelper:GetTableDataByID(ConfigNames.dictcalc_config, CommonCfgKey.TimeTokenSubDay)
        local value = tonumber(cfg.varval)
        local _ ,eTime= CommonFestivalDataManager:Get():GetActTime(self.actConfig.C_ID)
        local subT = CommonHelper:SubTime(eTime*TimeMilliSecond_Second)
        local day=math.abs( subT/TimeMilliSecond_Day)
        if day > value then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenDayNoBuy))
            return
        end
        CommonHelper:CSGameObjectSetActive(self.GetLevelView,true)
        self:BuyLevePreview(1)
    end)
    self.BtnGetExp = CommonHelper:HButtonSetCallback("BtnGetExp", self.center, function(data)
        self.ViewState=1
        TaskSubsystem:Get():SendMsg_GetTaskList(TimeTokenManager:Get():GetCurConfig().taskType)

    end)
    self.BtnGetAward = CommonHelper:HButtonSetCallback("BtnGetAward", self.center, function(data)
        self.ViewState=0
        CommonFestivalSubSystem:Get():SendMsg_ActTimeToken(self.actConfig.C_ID)
    end)

    self.activityList = UIUtil.GetTypeChildWightInputPath("InfoBaseScroll", self.TimeTokenView, typeof(MoreRowScrollView))
    self.viewbuyed =UIUtil.GetChild("viewbuyed", self.TimeTokenView)
    self.viewNormal = UIUtil.GetChild("viewNormal", self.TimeTokenView)

    self.BtnBuy = CommonHelper:HButtonSetCallback("BtnBuy", self.TimeTokenView, function(data)
        if TimeTokenManager:Get():GetTimeTokenInfoData().ifbuy then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenBuyed))
            return
        end
        CommonHelper:ChargeMoneyByID(tonumber(self.actConfig.itemids))
    end)

    self.BtnGetGift= CommonHelper:HButtonSetCallback("BtnGetGift", self.TimeTokenView, function(data)
        local isTips=true
        local timeTokenTable = TimeTokenManager:Get():GetTimeTokenTable()
        for i = 1, #timeTokenTable do
            if timeTokenTable[i].ifgift==0 and timeTokenTable[i].lev <= TimeTokenManager:Get():GetTimeTokenInfoData().lev  then
                isTips=false
                break
            end
            if TimeTokenManager:Get():GetTimeTokenInfoData().ifbuy and  timeTokenTable[i].ifgift==1 and timeTokenTable[i].lev <= TimeTokenManager:Get():GetTimeTokenInfoData().lev  then
                isTips=false
                break
            end
        end
        if isTips then
            CommonTipsHelper:Get():ShowCenterTips(CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenNoCanGetGift))
        else
            CommonFestivalSubSystem:Get():SendMsg_ActGiftTimeToken(self.actConfig.C_ID)
        end
    end)

    self.WillView = UIUtil.GetTypeChildWightInputPath("InfoBaseScroll", self.GetLevelView, typeof(MoreRowScrollView))

    CommonHelper:HButtonSetCallback("BtnClose1",self.GetLevelView,function(data)
        CommonHelper:CSGameObjectSetActive(self.GetLevelView,false)
    end)
    CommonHelper:HButtonSetCallback("BtnClose2",self.GetLevelView,function(data)
        CommonHelper:CSGameObjectSetActive(self.GetLevelView,false)
    end)
    CommonHelper:HButtonSetCallback("BtnSub",self.GetLevelView,function(data)
        self:BuyLevePreview(-1)
    end)
    CommonHelper:HButtonSetCallback("BtnAdd",self.GetLevelView,function(data)
        self:BuyLevePreview(1)
    end)
    self.BtnGetLv=CommonHelper:HButtonSetCallback("BtnGetLv",self.GetLevelView,function(data)
        CommonFestivalSubSystem:Get():SendMsg_ActUpTimeTokenLev(self.actConfig.C_ID,self.AddLev)
    end)

    self.ScrollView = UIUtil.GetTypeChildWightInputPath("ScrollView", self.TaskView, typeof(MoreRowScrollView))
    CommonHelper:HButtonSetCallback("BtnGetReward",self.TaskView,function(data)
        CommonHelper:CSGameObjectSetActive(self.TaskView,false)
        CommonFestivalSubSystem:Get():SendMsg_ActTimeToken(self.actConfig.C_ID)
    end)
end

function Page_CommonActTimeTokenView:RequestOpen()
    TimeTokenManager:Get():SetCurConfig(self.actConfig.C_ID)
    CommonFestivalSubSystem:Get():SendMsg_ActTimeToken(self.actConfig.C_ID)
end

function Page_CommonActTimeTokenView:OnOpen()
    self.ViewState=0
    CommonHelper:SetText("time/###time", self.center,self:GetDataTimeString())
    CommonHelper:CSGameObjectSetActive(self.TimeTokenView,true)
    CommonHelper:CSGameObjectSetActive(self.GetLevelView,false)
    CommonHelper:CSGameObjectSetActive(self.TaskView,false)

end

function Page_CommonActTimeTokenView:Refresh()
    self:LittlePageBtnRefresh()
    self.AddLev=0
    CommonHelper:CSGameObjectSetActive(self.TaskView,false)
    CommonHelper:CSGameObjectSetActive(self.GetLevelView,false)
    local timeTokenInfoData = TimeTokenManager:Get():GetTimeTokenInfoData()
    CommonHelper:SetText("###timetokenexp", self.center, CommonHelper:GetTempStr_Default(TemplateStringID.  TimeTokenExp, timeTokenInfoData.curExp, timeTokenInfoData.nextExp))
    CommonHelper:SetText("###timetokenlv", self.center, timeTokenInfoData.lev)
    CommonHelper:SetSlider("Slider", self.center, timeTokenInfoData.curExp / timeTokenInfoData.nextExp)
    if timeTokenInfoData.ifbuy then
        CommonHelper:SetGameObjectActive("###priceText",self.BtnBuy.gameObject,true)
        CommonHelper:SetGameObjectActive("moneycost",self.BtnBuy.gameObject,false)
        UIUtil.SetParentTransform(self.viewbuyed, self.activityList, true, true)
        CommonHelper:SetText("BtnBuy/###priceText", self.BtnBuy.gameObject, "<size=18>"..CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenBuyed).."</size>")
    else
        ---@type dictcharge_config_cell
        local chargeCfg =CommonHelper:GetChargeCfgByAreaAndItemId(tonumber(self.actConfig.itemids))
        UIUtil.SetParentTransform(self.viewNormal, self.activityList, true, true)
        CommonHelper:SetText("BtnBuy/###priceText", self.BtnBuy.gameObject, CommonHelper:GetTempStr_Default(TemplateStringID.TimeTokenBuyPrice, chargeCfg.pricename))
        CommonHelper:SetBtnIsRmbOrToken(self.BtnBuy,CommonHelper:GetChargeCfgByAreaAndItemId(tonumber(self.actConfig.itemids)))
    end
    CommonHelper:SetGameObjectActive("buyBg", self.center, timeTokenInfoData.ifbuy)
    CommonHelper:SetGameObjectActive("lockimage", self.center, timeTokenInfoData.ifbuy)
    local timeTokenTable=TimeTokenManager:Get():GetTimeTokenTable()
    self:BonusPreviewRefresh()
    CommonHelper:InitMoreRowScrollView(self.activityList, #timeTokenTable, 1, function(index, itemObj, scroll)

        local temp = timeTokenTable[index + 1]
        CommonHelper:SetText("###lv", itemObj,  temp.lev)
        CommonHelper:SetGameObjectActive("toplock", itemObj, temp.lev > timeTokenInfoData.lev)
        CommonHelper:SetGameObjectActive("bottomlock", itemObj, temp.lev > timeTokenInfoData.lev)
        if timeTokenInfoData.ifbuy  then
            CommonHelper:SetGameObjectActive("bottomlock", itemObj, temp.lev > timeTokenInfoData.lev)
        else
            CommonHelper:SetGameObjectActive("bottomlock", itemObj, true)
        end
        if temp.ifgift == nil or temp.ifgift == 0 then
            CommonHelper:SetGameObjectActive("toplockgeted", itemObj, false)
            CommonHelper:SetGameObjectActive("bottomlockgeted", itemObj, false)
        else
            CommonHelper:SetGameObjectActive("toplockgeted", itemObj, true)
            CommonHelper:SetGameObjectActive("bottomlockgeted", itemObj, temp.ifgift == 2)
        end

        local reward1 = UIUtil.GetChild("reward1", itemObj)
        local reward2 = UIUtil.GetChild("reward2", itemObj)
        local param1 = Param_ItemArticleParam()
        param1.count =temp.awardnums[1]---目前是一个奖励直接这么写了
        local param2 = Param_ItemArticleParam()
        param2.count =temp.hawardnums[1]---目前是一个奖励直接这么写了
        CommonHelper:SetItemComGroup(reward1, self:GetUIModuleID(), temp.awardids[1], param1, function(data)
            CommonHelper:ShowPartInfoByCfgId(tonumber(temp.awardids[1]), self:GetUIModuleID())
        end)
        CommonHelper:SetItemComGroup(reward2, self:GetUIModuleID(), temp.hawardids[1], param2, function(data)
            CommonHelper:ShowPartInfoByCfgId(temp.hawardids[1], self:GetUIModuleID())
        end)
        if temp.ispreviewbonus then
            if timeTokenInfoData.lev<=temp.lev and temp.ispreviewbonus then
                self:BonusPreviewRefresh(temp)
            end
        end

    end)
end

function Page_CommonActTimeTokenView:LittlePageBtnRefresh()
    CommonHelper:SetGameObjectActive("Bg1",self.BtnGetAward.gameObject,self.ViewState==0)
    CommonHelper:SetGameObjectActive("Bg2",self.BtnGetAward.gameObject,self.ViewState==1)
    CommonHelper:SetGameObjectActive("Bg1",self.BtnGetExp.gameObject,self.ViewState==1)
    CommonHelper:SetGameObjectActive("Bg2",self.BtnGetExp.gameObject,self.ViewState==0)
    CommonHelper:CSGameObjectSetActive(self.TaskView,self.ViewState==1)
    CommonHelper:CSGameObjectSetActive(self.TimeTokenView,self.ViewState==0)
end

---@param  tokenData TimeTokenData
function Page_CommonActTimeTokenView:BonusPreviewRefresh(tokenData)
    local timeTokenInfoData = TimeTokenManager:Get():GetTimeTokenInfoData()
    --CommonHelper:CSGameObjectSetActive(self.BtnGetGift.gameObject,timeTokenInfoData.lev<timeTokenInfoData.maxLev)
    if tokenData==nil  then
        local timeTokenTable = TimeTokenManager:Get():GetTimeTokenTable()
        for i = 1, #timeTokenTable do
            if timeTokenInfoData.lev<=timeTokenTable[i].lev and timeTokenTable[i].ispreviewbonus  then
                tokenData = timeTokenTable[i]
                break
            end
        end
    end
    if tokenData then
        CommonHelper:SetText("###lv", self. BonusPreview,  tokenData.lev)
        local reward1 = UIUtil.GetChild("reward1", self.BonusPreview)
        local reward2 = UIUtil.GetChild("reward2", self.BonusPreview)
        ---@type RewardData
        local temp1 = RewardData()
        temp1:SetDataIdNum(tokenData.awardids[1], tokenData.awardnums[1])
        local param1 = Param_ItemArticleParam()
        param1.count = temp1.num
        CommonHelper:SetItemComGroup(reward1, self:GetUIModuleID(), tonumber(temp1.id), param1, function(data)
            CommonHelper:ShowPartInfoByCfgId(tonumber(temp1.id), self:GetUIModuleID())
        end)

        local temp2 = RewardData()
        temp2:SetDataIdNum(tokenData.hawardids[1], tokenData.hawardnums[1])
        local param2 = Param_ItemArticleParam()
        param2.count = temp2.num
        CommonHelper:SetItemComGroup(reward2, self:GetUIModuleID(), tonumber(temp2.id), param2, function(data)
            CommonHelper:ShowPartInfoByCfgId(tonumber(temp2.id), self:GetUIModuleID())
        end)
    end
end

function Page_CommonActTimeTokenView:BuyLevePreview(addlev)
    local timeTokenInfoData = TimeTokenManager:Get():GetTimeTokenInfoData()
    if self.AddLev==nil then
        self.AddLev=addlev
    else
        self.AddLev= self.AddLev+addlev
        if self.AddLev<1 then
            self.AddLev=1
        end
    end
    if timeTokenInfoData.lev+self.AddLev>timeTokenInfoData.maxLev then
        self.AddLev = timeTokenInfoData.maxLev-timeTokenInfoData.lev
    end
    local cfg = CommonHelper:GetTableDataByID(ConfigNames.dictcalc_config,CommonCfgKey. TimeTokenLevelDiamond)
    local value=tonumber(cfg.varval)
    CommonHelper:SetText("###CurLv",self.GetLevelView,timeTokenInfoData.lev)
    CommonHelper:SetText("###DestLv",self.GetLevelView,timeTokenInfoData.lev+self.AddLev)
    CommonHelper:SetText("###buyhit",self.GetLevelView,CommonHelper:GetTempStr_Default(TemplateStringID.  TimeTokenBuyLevel,self.AddLev))
    CommonHelper:SetText("###paymoney",self.GetLevelView,self.AddLev*value)
    local CanGetList,_= TimeTokenManager:Get():GetCostTimeTokenAwardTable(timeTokenInfoData.lev,timeTokenInfoData.lev+self.AddLev)
    CommonHelper:InitMoreRowScrollView(self.WillView,#CanGetList,4,function(index, itemObj,scroll)
        ---@type RewardData
        local temp=CanGetList[index+1]
        local param = Param_ItemArticleParam()
        param.count = temp.num
        CommonHelper:SetItemComGroup(itemObj,self:GetUIModuleID() ,tonumber(temp.id),param,function(data)
            CommonHelper:ShowPartInfoByCfgId(tonumber(temp.id), self:GetUIModuleID() )
        end)
    end)
end

function Page_CommonActTimeTokenView:TaskViewRefresh()
    self:LittlePageBtnRefresh()
    local taskTable = TimeTokenManager:Get():GetTimeTaskTable()
    local timeTokenInfoData = TimeTokenManager:Get():GetTimeTokenInfoData()
    CommonHelper:SetText("###timetokenexp", self.center, CommonHelper:GetTempStr_Default(TemplateStringID.  TimeTokenExp, timeTokenInfoData.curExp, timeTokenInfoData.nextExp))
    CommonHelper:SetSlider("Slider", self.center, timeTokenInfoData.curExp / timeTokenInfoData.nextExp)
    CommonHelper:SetText("###timetokenlv", self.center, timeTokenInfoData.lev)
    CommonHelper:InitMoreRowScrollView(self.ScrollView,#taskTable,1,function(dataIndex,itemObj,scroll)
        ---@type TaskData
        local taskData=taskTable[dataIndex+1]
        local status1=  CommonHelper:SetGameObjectActive("task_item_1",itemObj,taskData.status<=TaskStatus.IsRally)
        local status2=  CommonHelper:SetGameObjectActive("task_item_2",itemObj,taskData.status==TaskStatus.IsDoneNoGet)
        local status3=  CommonHelper:SetGameObjectActive("task_item_3",itemObj,taskData.status==TaskStatus.IsDoneAndGet)
        local status
        if taskData.status<=TaskStatus.IsRally then
            status=status1
        end
        if taskData.status==TaskStatus.IsDoneNoGet then
            status=status2
        end
        if taskData.status==TaskStatus.IsDoneAndGet then
            status=status3
        end
        local alpha = taskData.status==TaskStatus.IsDoneAndGet and 0.5 or 1
        CommonHelper:SetGameObjectActive("completed",itemObj,taskData.status==TaskStatus.IsDoneAndGet)
        UIUtil.SetCanvasGroupAlpha("custom",itemObj,alpha,taskData.status~=TaskStatus.IsDoneAndGet)
        local value=0
        --  if taskData.status~=TaskStatus.IsDoneAndGet then
        value=taskData.finshNum/taskData.progress
        --end
        --CommonHelper:SetSlider("taskprogress",itemObj,value)
        CommonHelper:SetText("###taskdesc",taskData.description)
        local finshNum=taskData.finshNum
        local progress=taskData.progress
        if finshNum>progress then
            finshNum=progress
        end
        local progress=string.format(ClientDataManager:Get():GetTemplateString(TemplateStringID.TaskItemProgress),finshNum,progress)
        CommonHelper:SetText("###taskprogresscount",status,progress )

        local ScrollView_H= UIUtil.GetTypeChildWightInputPath("ScrollView_H", itemObj, typeof(MoreRowScrollView))
        CommonHelper:InitMoreRowScrollView(ScrollView_H,  #taskData.rewards, 1,function(awardIndex, awardItem, scroll)
            if taskData.rewards[awardIndex+1] then
                local param = Param_ItemArticleParam()
                param.count = taskData.rewards[awardIndex+1].num
                CommonHelper:SetItemComGroup(awardItem,self:GetUIModuleID(),tonumber(taskData.rewards[awardIndex+1].id),param,function(data)
                    CommonHelper:ShowPartInfoByCfgId(tonumber(taskData.rewards[awardIndex+1].id), self:GetUIModuleID())
                end)
            end
            CommonHelper:CSGameObjectSetActive(awardItem,taskData.rewards[awardIndex+1]~=nil)
        end)

        local btnTask=CommonHelper:HButtonSetCallback("btntaskitem",itemObj,function(tempData)
            if taskTable[tempData.intData+1].status==TaskStatus.IsDoneNoGet then
                TaskSubsystem:Get():SendMsg_GetReward(taskTable[tempData.intData+1].questType,taskTable[tempData.intData+1].taskId,taskTable[tempData.intData+1].day)
            end
        end,dataIndex)
        CommonHelper:SetGameObjectActive("btntaskitem",itemObj,taskData.status~=TaskStatus.IsDoneAndGet)
        CommonHelper:SetToggleState(btnTask,taskData.status==TaskStatus.IsDoneNoGet)
        CommonHelper:SetHButtonClick(btnTask,taskData.status==TaskStatus.IsDoneNoGet,false)
    end)
end